// Third wave — the last common Kali/security tools not covered by
// kali-{shallow,deep,extra,extra2}. Same tool() factory pattern for
// consistency; every entry ships at least one hand-authored command
// and one real error alongside the auto-generated help/notFound.
import type { KaliTool, KaliCategory, Command, KnownError } from "./types";

const help = (inv: string): Command[] => [
  {
    name: `${inv} --help`,
    syntax: `${inv} --help`,
    description: "Print built-in usage and exit.",
    examples: [{ code: `${inv} --help | less`, note: "Page through the full help." }],
    bestScenario: "Fast flag lookup at the terminal.",
    category: "Reference",
  },
  {
    name: `man ${inv.split(" ")[0]}`,
    syntax: `man ${inv.split(" ")[0]}`,
    description: "Read the packaged man page.",
    examples: [{ code: `man ${inv.split(" ")[0]}`, note: "Authoritative reference." }],
    bestScenario: "When --help omits protocol or format details.",
    category: "Reference",
  },
];

const notFound = (inv: string): KnownError[] => [
  {
    message: `${inv}: command not found`,
    cause: "Package not installed, or the binary is under /usr/sbin and not in $PATH.",
    fix: "sudo apt install <package>, then re-open the shell or export PATH=$PATH:/usr/sbin.",
  },
];

function tool(
  slug: string,
  name: string,
  category: KaliCategory,
  pkg: string,
  invocation: string,
  summary: string,
  extra: Command[] = [],
  extraErrors: KnownError[] = [],
  homepage = "",
): KaliTool {
  return {
    slug,
    name,
    category,
    package: pkg,
    homepage,
    summary,
    depth: "shallow",
    invocation,
    commands: [...extra, ...help(invocation)],
    errors: [...extraErrors, ...notFound(invocation)],
  };
}

const cmd = (
  name: string,
  syntax: string,
  description: string,
  example: string,
  note: string,
  bestScenario: string,
  category = "Usage",
): Command => ({
  name,
  syntax,
  description,
  examples: [{ code: example, note }],
  bestScenario,
  category,
});

const err = (message: string, cause: string, fix: string): KnownError => ({ message, cause, fix });

